def _get_version(version_info):
    " Returns a PEP 440-compliant version number from `version_info`. "
    assert len(version_info) == 5
    assert version_info[3] in ('dev', 'alpha', 'beta', 'rc', 'final')

    parts = 2 if version_info[2] == 0 else 3
    v = '.'.join(map(str, version_info[:parts]))

    if version_info[3] == 'dev':
        v += '.dev' + str(version_info[4])
    elif version_info[3] != 'final':
        mapping = {'alpha': 'a', 'beta': 'b', 'rc': 'rc'}
        v += mapping[version_info[3]] + str(version_info[4])

    return v

def set(self, state: Any):
    """ Set a new state. """
    self.append(state)

def reset(self) -> None:
    """ Step back one step in nested state. """
    self.pop()

def isstate(self, state: Any) -> bool:
    """ Test that top (current) level is of given state. """
    if len(self):
        return self[-1] == state
    else:
        return False

def __init__(self, parser: BlockParser):
    self.parser = parser
    self.tab_length = parser.md.tab_length

def lastChild(self, parent: etree.Element) -> etree.Element | None:
    """ Return the last child of an `etree` element. """
    if len(parent):
        return parent[-1]
    else:
        return None

def detab(self, text: str, length: int | None = None) -> tuple[str, str]:
    """ Remove a tab from the front of each line of the given text. """
    if length is None:
        length = self.tab_length
    newtext = []
    lines = text.split('\n')
    for line in lines:
        if line.startswith(' ' * length):
            newtext.append(line[length:])
        elif not line.strip():
            newtext.append('')
        else:
            break
    return '\n'.join(newtext), '\n'.join(lines[len(newtext):])

def looseDetab(self, text: str, level: int = 1) -> str:
    """ Remove a tab from front of lines but allowing dedented lines. """
    lines = text.split('\n')
    for i in range(len(lines)):
        if lines[i].startswith(' '*self.tab_length*level):
            lines[i] = lines[i][self.tab_length*level:]
    return '\n'.join(lines)

def __init__(self, *args):
    super().__init__(*args)
    self.INDENT_RE = re.compile(r'^(([ ]{%s})+)' % self.tab_length)

class BlockQuoteProcessor(BlockProcessor):
    """ Process blockquotes. """

    RE = re.compile(r'(^|\n)[ ]{0,3}>[ ]?(.*)')

    def test(self, parent: etree.Element, block: str) -> bool:
        return bool(self.RE.search(block)) and not util.nearing_recursion_limit()

    def run(self, parent: etree.Element, blocks: list[str]) -> None:
        block = blocks.pop(0)
        m = self.RE.search(block)
        if m:
            before = block[:m.start()]  # Lines before blockquote
            # Pass lines before blockquote in recursively for parsing first.
            self.parser.parseBlocks(parent, [before])
            # Remove `> ` from beginning of each line.
            block = '\n'.join(
                [self.clean(line) for line in block[m.start():].split('\n')]
            )
        sibling = self.lastChild(parent)
        if sibling is not None and sibling.tag == "blockquote":
            # Previous block was a blockquote so set that as this blocks parent
            quote = sibling
        else:
            # This is a new blockquote. Create a new parent element.
            quote = etree.SubElement(parent, 'blockquote')
        # Recursively parse block with blockquote as parent.
        # change parser state so blockquotes embedded in lists use `p` tags
        self.parser.state.set('blockquote')
        self.parser.parseChunk(quote, block)
        self.parser.state.reset()

    def clean(self, line: str) -> str:
        """ Remove `>` from beginning of a line. """
        m = self.RE.match(line)
        if line.strip() == ">":
            return ""
        elif m:
            return m.group(2)
        else:
            return line

def clean(self, line: str) -> str:
    """ Remove `>` from beginning of a line. """
    m = self.RE.match(line)
    if line.strip() == ">":
        return ""
    elif m:
        return m.group(2)
    else:
        return line

def test(self, parent: etree.Element, block: str) -> bool:
    # As in `ListIndentProcessor`, nesting stops short of the recursion limit.
    # `UListProcessor` inherits this method, so unordered lists are covered too.
    return bool(self.RE.match(block)) and not util.nearing_recursion_limit()

def test(self, parent: etree.Element, block: str) -> bool:
    # Check for a line starting with `#` before running the regex, which is
    # slow to scan long blocks.
    return (block.startswith('#') or '\n#' in block) and bool(self.RE.search(block))

class SetextHeaderProcessor(BlockProcessor):
    """ Process Setext-style Headers. """

    # Detect Setext-style header. Must be first 2 lines of block.
    RE = re.compile(r'^.*?\n(?:=+|-+)[ ]*(\n|$)', re.MULTILINE)

    def test(self, parent: etree.Element, block: str) -> bool:
        return bool(self.RE.match(block))

    def run(self, parent: etree.Element, blocks: list[str]) -> None:
        lines = blocks.pop(0).split('\n', 2)
        # Determine level. `=` is 1 and `-` is 2.
        if lines[1].startswith('='):
            level = 1
        else:
            level = 2
        h = etree.SubElement(parent, 'h%d' % level)
        h.text = lines[0].strip()
        if len(lines) > 2:
            # Block contains additional lines. Add to  master blocks for later.
            blocks.insert(0, lines[2])

def run(self, parent: etree.Element, blocks: list[str]) -> None:
    lines = blocks.pop(0).split('\n', 2)
    # Determine level. `=` is 1 and `-` is 2.
    if lines[1].startswith('='):
        level = 1
    else:
        level = 2
    h = etree.SubElement(parent, 'h%d' % level)
    h.text = lines[0].strip()
    if len(lines) > 2:
        # Block contains additional lines. Add to  master blocks for later.
        blocks.insert(0, lines[2])

class EmptyBlockProcessor(BlockProcessor):
    """ Process blocks that are empty or start with an empty line. """

    def test(self, parent: etree.Element, block: str) -> bool:
        return not block or block.startswith('\n')

    def run(self, parent: etree.Element, blocks: list[str]) -> None:
        block = blocks.pop(0)
        filler = '\n\n'
        if block:
            # Starts with empty line
            # Only replace a single line.
            filler = '\n'
            # Save the rest for later.
            theRest = block[1:]
            if theRest:
                # Add remaining lines to master blocks for later.
                blocks.insert(0, theRest)
        sibling = self.lastChild(parent)
        if (sibling is not None and sibling.tag == 'pre' and
           len(sibling) and sibling[0].tag == 'code'):
            # Last block is a code block. Append to preserve whitespace.
            sibling[0].text = util.AtomicString(
                '{}{}'.format(sibling[0].text, filler)
            )

class ParagraphProcessor(BlockProcessor):
    """ Process Paragraph blocks. """

    def test(self, parent: etree.Element, block: str) -> bool:
        return True

    def run(self, parent: etree.Element, blocks: list[str]) -> None:
        block = blocks.pop(0)
        if block.strip():
            # Not a blank block. Add to parent, otherwise throw it away.
            if self.parser.state.isstate('list'):
                # The parent is a tight-list.
                #
                # Check for any children. This will likely only happen in a
                # tight-list when a header isn't followed by a blank line.
                # For example:
                #
                #     * # Header
                #     Line 2 of list item - not part of header.
                sibling = self.lastChild(parent)
                if sibling is not None:
                    # Insert after sibling.
                    if sibling.tail:
                        sibling.tail = '{}\n{}'.format(sibling.tail, block)
                    else:
                        sibling.tail = '\n%s' % block
                else:
                    # Append to parent.text
                    if parent.text:
                        parent.text = '{}\n{}'.format(parent.text, block)
                    else:
                        parent.text = block.lstrip()
            else:
                # Create a regular paragraph
                p = etree.SubElement(parent, 'p')
                p.text = block.lstrip()

def run(self, parent: etree.Element, blocks: list[str]) -> None:
    block = blocks.pop(0)
    if block.strip():
        # Not a blank block. Add to parent, otherwise throw it away.
        if self.parser.state.isstate('list'):
            # The parent is a tight-list.
            #
            # Check for any children. This will likely only happen in a
            # tight-list when a header isn't followed by a blank line.
            # For example:
            #
            #     * # Header
            #     Line 2 of list item - not part of header.
            sibling = self.lastChild(parent)
            if sibling is not None:
                # Insert after sibling.
                if sibling.tail:
                    sibling.tail = '{}\n{}'.format(sibling.tail, block)
                else:
                    sibling.tail = '\n%s' % block
            else:
                # Append to parent.text
                if parent.text:
                    parent.text = '{}\n{}'.format(parent.text, block)
                else:
                    parent.text = block.lstrip()
        else:
            # Create a regular paragraph
            p = etree.SubElement(parent, 'p')
            p.text = block.lstrip()

def reset(self) -> Markdown:
    """
    Resets all state variables to prepare the parser instance for new input.

    Called once upon creation of a class instance. Should be called manually between calls
    to [`Markdown.convert`][markdown.Markdown.convert].
    """
    self.htmlStash.reset()
    self.references.clear()

    if self.delimiters is not None:
        self.delimiters.reset()
        if self.delimiters not in self.inlinePatterns:
            self.delimiters = None

    for extension in self.registeredExtensions:
        if hasattr(extension, 'reset'):
            extension.reset()

    return self

def __init__(self, **kwargs):
    """ Initiate Extension and set up configs. """
    self.setConfigs(kwargs)

class AbbrExtension(Extension):
    """ Abbreviation Extension for Python-Markdown. """

    def __init__(self, **kwargs):
        """ Initiate Extension and set up configs. """
        self.config = {
            'glossary': [
                {},
                'A dictionary where the `key` is the abbreviation and the `value` is the definition.'
                "Default: `{}`"
            ],
        }
        """ Default configuration options. """
        super().__init__(**kwargs)
        self.abbrs = {}
        self.glossary = {}

    def reset(self):
        """ Clear all previously defined abbreviations. """
        self.abbrs.clear()
        if (self.glossary):
            self.abbrs.update(self.glossary)

    def reset_glossary(self):
        """ Clear all abbreviations from the glossary. """
        self.glossary.clear()

    def load_glossary(self, dictionary: dict[str, str]):
        """Adds `dictionary` to our glossary. Any abbreviations that already exist will be overwritten."""
        if dictionary:
            self.glossary = {**dictionary, **self.glossary}

    def extendMarkdown(self, md):
        """
        Register the processors.

        | Class Instance                                                      | Registry                                                         | Name   | Priority |
        | ------------------------------------------------------------------- | ---------------------------------------------------------------- | ------ | :------: |
        | [`AbbrTreeprocessor`][markdown.extensions.abbr.AbbrTreeprocessor]   | [`treeprocessors`][markdown.treeprocessors.build_treeprocessors] | `abbr` | `7`      |
        | [`AbbrBlockprocessor`][markdown.extensions.abbr.AbbrBlockprocessor] | [`blockprocessors`][markdown.blockprocessors.build_block_parser] | `abbr` | `16`     |

        """
        # flake8: noqa: E501 75-78
        if (self.config['glossary'][0]):
            self.load_glossary(self.config['glossary'][0])
        self.abbrs.update(self.glossary)
        md.registerExtension(self)
        md.treeprocessors.register(AbbrTreeprocessor(md, self.abbrs), 'abbr', 7)
        md.parser.blockprocessors.register(AbbrBlockprocessor(md.parser, self.abbrs), 'abbr', 16)

def __init__(self, **kwargs):
    """ Initiate Extension and set up configs. """
    self.config = {
        'glossary': [
            {},
            'A dictionary where the `key` is the abbreviation and the `value` is the definition.'
            "Default: `{}`"
        ],
    }
    """ Default configuration options. """
    super().__init__(**kwargs)
    self.abbrs = {}
    self.glossary = {}

def reset(self):
    """ Clear all previously defined abbreviations. """
    self.abbrs.clear()
    if (self.glossary):
        self.abbrs.update(self.glossary)

def reset_glossary(self):
    """ Clear all abbreviations from the glossary. """
    self.glossary.clear()

def load_glossary(self, dictionary: dict[str, str]):
    """Adds `dictionary` to our glossary. Any abbreviations that already exist will be overwritten."""
    if dictionary:
        self.glossary = {**dictionary, **self.glossary}

class AbbrTreeprocessor(Treeprocessor):
    """ Replace abbreviation text with `<abbr>` elements. """

    def __init__(self, md: Markdown | None = None, abbrs: dict | None = None):
        self.abbrs: dict = abbrs if abbrs is not None else {}
        self.RE: re.RegexObject | None = None
        super().__init__(md)

    def create_element(self, title: str, text: str, tail: str) -> etree.Element:
        ''' Create an `abbr` element. '''
        abbr = etree.Element('abbr', {'title': title})
        abbr.text = AtomicString(text)
        abbr.tail = tail
        return abbr

    def iter_element(self, el: etree.Element, parent: etree.Element | None = None) -> None:
        ''' Recursively iterate over elements, run regex on text and wrap matches in `abbr` tags. '''
        for child in reversed(el):
            self.iter_element(child, el)
        if text := el.text:
            if not isinstance(text, AtomicString):
                for m in reversed(list(self.RE.finditer(text))):
                    if self.abbrs[m.group(0)]:
                        abbr = self.create_element(self.abbrs[m.group(0)], m.group(0), text[m.end():])
                        el.insert(0, abbr)
                        text = text[:m.start()]
                el.text = text
        if parent is not None and el.tail:
            tail = el.tail
            index = list(parent).index(el) + 1
            if not isinstance(tail, AtomicString):
                for m in reversed(list(self.RE.finditer(tail))):
                    if self.abbrs[m.group(0)]:
                        abbr = self.create_element(self.abbrs[m.group(0)], m.group(0), tail[m.end():])
                        parent.insert(index, abbr)
                        tail = tail[:m.start()]
                el.tail = tail

    def run(self, root: etree.Element) -> etree.Element | None:
        ''' Step through tree to find known abbreviations. '''
        if not self.abbrs:
            # No abbreviations defined. Skip running processor.
            return
        # Build and compile regex
        abbr_list = list(self.abbrs.keys())
        abbr_list.sort(key=len, reverse=True)
        self.RE = re.compile(f"\\b(?:{ '|'.join(re.escape(key) for key in abbr_list) })\\b")
        # Step through tree and modify on matches
        self.iter_element(root)

def __init__(self, md: Markdown | None = None, abbrs: dict | None = None):
    self.abbrs: dict = abbrs if abbrs is not None else {}
    self.RE: re.RegexObject | None = None
    super().__init__(md)

def iter_element(self, el: etree.Element, parent: etree.Element | None = None) -> None:
    ''' Recursively iterate over elements, run regex on text and wrap matches in `abbr` tags. '''
    for child in reversed(el):
        self.iter_element(child, el)
    if text := el.text:
        if not isinstance(text, AtomicString):
            for m in reversed(list(self.RE.finditer(text))):
                if self.abbrs[m.group(0)]:
                    abbr = self.create_element(self.abbrs[m.group(0)], m.group(0), text[m.end():])
                    el.insert(0, abbr)
                    text = text[:m.start()]
            el.text = text
    if parent is not None and el.tail:
        tail = el.tail
        index = list(parent).index(el) + 1
        if not isinstance(tail, AtomicString):
            for m in reversed(list(self.RE.finditer(tail))):
                if self.abbrs[m.group(0)]:
                    abbr = self.create_element(self.abbrs[m.group(0)], m.group(0), tail[m.end():])
                    parent.insert(index, abbr)
                    tail = tail[:m.start()]
            el.tail = tail

class AbbrBlockprocessor(BlockProcessor):
    """ Parse text for abbreviation references. """

    RE = re.compile(r'^[*]\[(?P<abbr>[^\\]*?)\][ ]?:[ ]*\n?[ ]*(?P<title>.*)$', re.MULTILINE)

    def __init__(self, parser: BlockParser, abbrs: dict):
        self.abbrs: dict = abbrs
        super().__init__(parser)

    def test(self, parent: etree.Element, block: str) -> bool:
        return True

    def run(self, parent: etree.Element, blocks: list[str]) -> bool:
        """
        Find and remove all abbreviation references from the text.
        Each reference is added to the abbreviation collection.

        """
        block = blocks.pop(0)
        m = self.RE.search(block)
        if m:
            abbr = m.group('abbr').strip()
            title = m.group('title').strip()
            if title and abbr:
                if title == "''" or title == '""':
                    self.abbrs.pop(abbr, None)
                else:
                    self.abbrs[abbr] = title
                if block[m.end():].strip():
                    # Add any content after match back to blocks as separate block
                    blocks.insert(0, block[m.end():].lstrip('\n'))
                if block[:m.start()].strip():
                    # Add any content before match back to blocks as separate block
                    blocks.insert(0, block[:m.start()].rstrip('\n'))
                return True
        # No match. Restore block.
        blocks.insert(0, block)
        return False

def __init__(self, parser: BlockParser, abbrs: dict):
    self.abbrs: dict = abbrs
    super().__init__(parser)

@deprecated("This class will be removed in the future; use `AbbrTreeprocessor` instead.")
class AbbrInlineProcessor(InlineProcessor):
    """ Abbreviation inline pattern. """

    def __init__(self, pattern: str, title: str):
        super().__init__(pattern)
        self.title = title

    def handleMatch(self, m: re.Match[str], data: str) -> tuple[etree.Element, int, int]:
        abbr = etree.Element('abbr')
        abbr.text = AtomicString(m.group('abbr'))
        abbr.set('title', self.title)
        return abbr, m.start(0), m.end(0)

def __init__(self, pattern: str, title: str):
    super().__init__(pattern)
    self.title = title

def handleMatch(self, m: re.Match[str], data: str) -> tuple[etree.Element, int, int]:
    abbr = etree.Element('abbr')
    abbr.text = AtomicString(m.group('abbr'))
    abbr.set('title', self.title)
    return abbr, m.start(0), m.end(0)

def test(self, parent: etree.Element, block: str) -> bool:

    # Check for the marker before running the regex, which is slow to scan
    # long blocks. Blocks which other processors split one line at a time
    # get tested again and again.
    if '!!!' in block and self.RE.search(block):
        return True
    else:
        return self.parse_content(parent, block)[0] is not None

def _handle_double_quote(s, t):
    k, v = t.split('=', 1)
    return k, v.strip('"')

def _handle_single_quote(s, t):
    k, v = t.split('=', 1)
    return k, v.strip("'")

def sanitize_name(name: str) -> str:
    """
    Sanitize name as 'an XML Name, minus the `:`.'
    See <https://www.w3.org/TR/REC-xml-names/#NT-NCName>.
    """
    return NAME_RE.sub('_', name)

class AttrListTreeprocessor(Treeprocessor):

    BASE_RE = r'\{\:?[ ]*([^\}\n ][^\n]*)\}'
    HEADER_RE = re.compile(r'[ ]+{}[ ]*$'.format(BASE_RE))
    BLOCK_RE = re.compile(r'\n[ ]*{}[ ]*$'.format(BASE_RE))
    INLINE_RE = re.compile(r'^{}'.format(BASE_RE))
    NAME_RE = NAME_RE

    def run(self, doc: Element) -> None:
        for elem in doc.iter():
            if self.md.is_block_level(elem.tag):
                # Block level: check for `attrs` on last line of text
                RE = self.BLOCK_RE
                if isheader(elem) or elem.tag in ['dt', 'td', 'th']:
                    # header, def-term, or table cell: check for attributes at end of element
                    RE = self.HEADER_RE
                if len(elem) and elem.tag == 'li':
                    # special case list items. children may include a `ul` or `ol`.
                    pos = None
                    # find the `ul` or `ol` position
                    for i, child in enumerate(elem):
                        if child.tag in ['ul', 'ol']:
                            pos = i
                            break
                    if pos is None and elem[-1].tail:
                        # use tail of last child. no `ul` or `ol`.
                        m = RE.search(elem[-1].tail)
                        if m:
                            if not self.assign_attrs(elem, m.group(1), strict=True):
                                elem[-1].tail = elem[-1].tail[:m.start()]
                    elif pos is not None and pos > 0 and elem[pos-1].tail:
                        # use tail of last child before `ul` or `ol`
                        m = RE.search(elem[pos-1].tail)
                        if m:
                            if not self.assign_attrs(elem, m.group(1), strict=True):
                                elem[pos-1].tail = elem[pos-1].tail[:m.start()]
                    elif elem.text:
                        # use text. `ul` is first child.
                        m = RE.search(elem.text)
                        if m:
                            if not self.assign_attrs(elem, m.group(1), strict=True):
                                elem.text = elem.text[:m.start()]
                elif len(elem) and elem[-1].tail:
                    # has children. Get from tail of last child
                    m = RE.search(elem[-1].tail)
                    if m:
                        if not self.assign_attrs(elem, m.group(1), strict=True):
                            elem[-1].tail = elem[-1].tail[:m.start()]
                            if isheader(elem):
                                # clean up trailing #s
                                elem[-1].tail = elem[-1].tail.rstrip('#').rstrip()
                elif elem.text:
                    # no children. Get from text.
                    m = RE.search(elem.text)
                    if m:
                        if not self.assign_attrs(elem, m.group(1), strict=True):
                            elem.text = elem.text[:m.start()]
                            if isheader(elem):
                                # clean up trailing #s
                                elem.text = elem.text.rstrip('#').rstrip()
            else:
                # inline: check for `attrs` at start of tail
                if elem.tail:
                    m = self.INLINE_RE.match(elem.tail)
                    if m:
                        remainder = self.assign_attrs(elem, m.group(1))
                        elem.tail = elem.tail[m.end():] + remainder

    def assign_attrs(self, elem: Element, attrs_string: str, *, strict: bool = False) -> str:
        """ Assign `attrs` to element.

        If the `attrs_string` has an extra closing curly brace, the remaining text is returned.

        The `strict` argument controls whether to still assign `attrs` if there is a remaining `}`.
        """
        attrs, remainder = get_attrs_and_remainder(attrs_string)
        if strict and remainder:
            return remainder

        for k, v in attrs:
            if k == '.':
                # add to class
                cls = elem.get('class')
                if cls:
                    elem.set('class', '{} {}'.format(cls, v))
                else:
                    elem.set('class', v)
            elif v is None:
                # assign a valueless attribute. Maintain the historic
                # `key="key"` representation only for known boolean
                # attributes (which differ per output format). For any
                # other attribute, preserve what the user provided by
                # keeping the value as `None`, which the serializer
                # renders as the bare attribute name.
                name = self.sanitize_name(k)
                if name.lower() in BOOLEAN_ATTRIBUTES.get(self.md.output_format, frozenset()):
                    elem.set(name, name)
                else:
                    elem.set(name, None)
            else:
                # assign attribute `k` with `v`
                elem.set(self.sanitize_name(k), v)
        # The text that we initially over-matched will be put back.
        return remainder

    def sanitize_name(self, name: str) -> str:
        """
        Sanitize name as 'an XML Name, minus the `:`.'
        See <https://www.w3.org/TR/REC-xml-names/#NT-NCName>.
        """
        return sanitize_name(name)

