def __init__(self, **kwargs):
    self.config = {
        'lang_prefix': ['language-', 'Prefix prepended to the language. Default: "language-"']
    }
    """ Default configuration options. """
    super().__init__(**kwargs)

def run(self, lines: list[str]) -> list[str]:
    """ Match and store Fenced Code Blocks in the `HtmlStash`. """

    # Check for dependent extensions
    if not self.checked_for_deps:
        for ext in self.md.registeredExtensions:
            if isinstance(ext, CodeHiliteExtension):
                self.codehilite_conf = ext.getConfigs()
            if isinstance(ext, AttrListExtension):
                self.use_attr_list = True

        self.checked_for_deps = True

    text = "\n".join(lines)
    # Collect the output in pieces, as rebuilding the full text after each block is quadratic.
    pieces: list[str] = []
    last = 0
    index = 0
    while 1:
        m = self.FENCED_BLOCK_RE.search(text, index)
        if m:
            lang, id, classes, config = None, '', [], {}
            if m.group('attrs'):
                attrs, remainder = get_attrs_and_remainder(m.group('attrs'))
                if remainder:  # Does not have correctly matching curly braces, so the syntax is invalid.
                    index = m.end('attrs')  # Explicitly skip over this, to prevent an infinite loop.
                    continue
                id, classes, config = self.handle_attrs(attrs)
                if len(classes):
                    lang = classes.pop(0)
            else:
                if m.group('lang'):
                    lang = m.group('lang')
                if m.group('hl_lines'):
                    # Support `hl_lines` outside of `attrs` for backward-compatibility
                    config['hl_lines'] = parse_hl_lines(m.group('hl_lines'))

            # If `config` is not empty, then the `codehighlite` extension
            # is enabled, so we call it to highlight the code
            if self.codehilite_conf and self.codehilite_conf['use_pygments'] and config.get('use_pygments', True):
                local_config = self.codehilite_conf.copy()
                local_config.update(config)
                # Combine classes with `cssclass`. Ensure `cssclass` is at end
                # as Pygments appends a suffix under certain circumstances.
                # Ignore ID as Pygments does not offer an option to set it.
                if classes:
                    local_config['css_class'] = '{} {}'.format(
                        ' '.join(classes),
                        local_config['css_class']
                    )
                highliter = CodeHilite(
                    m.group('code'),
                    lang=lang,
                    style=local_config.pop('pygments_style', 'default'),
                    **local_config
                )

                code = highliter.hilite(shebang=False)
            else:
                id_attr = lang_attr = class_attr = kv_pairs = ''
                if lang:
                    prefix = self.config.get('lang_prefix', 'language-')
                    lang_attr = f' class="{prefix}{_escape_attrib_html(lang)}"'
                if classes:
                    class_attr = f' class="{_escape_attrib_html(" ".join(classes))}"'
                if id:
                    id_attr = f' id="{_escape_attrib_html(id)}"'
                if self.use_attr_list and config and not config.get('use_pygments', False):
                    # Only assign key/value pairs to code element if `attr_list` extension is enabled, key/value
                    # pairs were defined on the code block, and the `use_pygments` key was not set to `True`. The
                    # `use_pygments` key could be either set to `False` or not defined. It is omitted from output.
                    kv_pairs = ''.join(
                        f' {sanitize_name(k)}="{_escape_attrib_html(v)}"'
                        for k, v in config.items() if k != 'use_pygments'
                    )
                code = self._escape(m.group('code'))
                code = f'<pre{id_attr}{class_attr}><code{lang_attr}{kv_pairs}>{code}</code></pre>'

            placeholder = self.md.htmlStash.store(code)
            pieces.append(f'{text[last:m.start()]}\n{placeholder}\n')
            # Continue from after the replaced text in the next iteration.
            index = last = m.end()
        else:
            break
    pieces.append(text[last:])
    return "".join(pieces).split("\n")

def handle_attrs(
    self, attrs: Iterable[tuple[str, str | None]]
) -> tuple[str, list[str], dict[str, Any]]:
    """ Return tuple: `(id, [list, of, classes], {configs})` """
    id = ''
    classes = []
    configs = {}
    for k, v in attrs:
        if v is None:
            # A valueless attribute is a flag: preserve the
            # historic behavior of using the key as its own value.
            v = k
        if k == 'id':
            id = v
        elif k == '.':
            classes.append(v)
        elif k == 'hl_lines':
            configs[k] = parse_hl_lines(v)
        elif k in self.bool_options:
            configs[k] = parseBoolValue(v, fail_on_errors=False, preserve_none=True)
        else:
            configs[k] = v
    return id, classes, configs

class FootnoteExtension(Extension):
    """ Footnote Extension. """

    def __init__(self, **kwargs):
        """ Setup configs. """

        self.config = {
            'PLACE_MARKER': [
                '///Footnotes Go Here///', 'The text string that marks where the footnotes go'
            ],
            'UNIQUE_IDS': [
                False, 'Avoid name collisions across multiple calls to `reset()`.'
            ],
            'BACKLINK_TEXT': [
                '&#8617;', "The text string that links from the footnote to the reader's place."
            ],
            'SUPERSCRIPT_TEXT': [
                '{}', "The text string that links from the reader's place to the footnote."
            ],
            'BACKLINK_TITLE': [
                'Jump back to footnote %d in the text',
                'The text string used for the title HTML attribute of the backlink. '
                '%d will be replaced by the footnote number.'
            ],
            'SEPARATOR': [
                ':', 'Footnote separator.'
            ],
            'USE_DEFINITION_ORDER': [
                True,
                'Order footnote labels by definition order (True) or by document order (False). '
                'Default: True.'
            ]
        }
        """ Default configuration options. """
        super().__init__(**kwargs)

        # In multiple invocations, emit links that don't get tangled.
        self.unique_prefix = 0
        self.found_refs: dict[str, int] = {}
        self.used_refs: set[str] = set()

        # Backward compatibility with old '%d' placeholder
        self.setConfig('BACKLINK_TITLE', self.getConfig("BACKLINK_TITLE").replace("%d", "{}"))

        self.reset()

    def extendMarkdown(self, md):
        """ Register the processors.

        | Class Instance                                                              | Registry                                                         | Name   | Priority |
        | --------------------------------------------------------------------------- | ---------------------------------------------------------------- | ------ | :------: |
        | [`FootnoteBlockProcessor`][markdown.extensions.footnotes.FootnoteBlockProcessor] | [`blockprocessors`][markdown.blockprocessors.build_block_parser] | `footnote` | `17` |
        | [`FootnoteInlineProcessor`][markdown.extensions.footnotes.FootnoteInlineProcessor] | [`inlinepatterns`][markdown.inlinepatterns.build_inlinepatterns] | `footnote` | `175` |
        | [`FootnoteTreeprocessor`][markdown.extensions.footnotes.FootnoteTreeprocessor] | [`treeprocessors`][markdown.treeprocessors.build_treeprocessors] | `footnote` | `50` |
        | [`FootnoteReorderingProcessor`][markdown.extensions.footnotes.FootnoteReorderingProcessor] | [`treeprocessors`][markdown.treeprocessors.build_treeprocessors] | `footnote-reorder` | `19` |
        | [`FootnotePostTreeprocessor`][markdown.extensions.footnotes.FootnotePostTreeprocessor] | [`treeprocessors`][markdown.treeprocessors.build_treeprocessors] | `footnote-duplicate` | `15` |
        | [`FootnotePostprocessor`][markdown.extensions.footnotes.FootnotePostprocessor] | [`postprocessors`][markdown.postprocessors.build_postprocessors] | `footnote` | `25` |

        """
        # flake8: noqa: E501 88-95
        md.registerExtension(self)
        self.parser = md.parser
        self.md = md
        # Insert a `blockprocessor` before `ReferencePreprocessor`
        md.parser.blockprocessors.register(FootnoteBlockProcessor(self), 'footnote', 17)

        # Insert an inline pattern before `ImageReferencePattern`
        FOOTNOTE_RE = r'\[\^([^\]]*)\]'  # blah blah [^1] blah
        md.inlinePatterns.register(FootnoteInlineProcessor(FOOTNOTE_RE, self), 'footnote', 175)
        # Insert a tree-processor that would actually add the footnote div
        # This must be before all other tree-processors (i.e., `inline` and
        # `codehilite`) so they can run on the contents of the div.
        md.treeprocessors.register(FootnoteTreeprocessor(self), 'footnote', 50)

        # Insert a tree-processor to reorder the footnotes if necessary. This must be after
        # `inline` tree-processor so it can access the footnote reference order
        # (`self.footnote_order`) that gets populated by the `FootnoteInlineProcessor`.
        if not self.getConfig("USE_DEFINITION_ORDER"):
            md.treeprocessors.register(FootnoteReorderingProcessor(self), 'footnote-reorder', 19)

        # Insert a tree-processor that will run after inline is done.
        # In this tree-processor we want to check our duplicate footnote tracker
        # And add additional `backrefs` to the footnote pointing back to the
        # duplicated references.
        md.treeprocessors.register(FootnotePostTreeprocessor(self), 'footnote-duplicate', 15)

        # Insert a postprocessor after amp_substitute processor
        md.postprocessors.register(FootnotePostprocessor(self), 'footnote', 25)

    def reset(self) -> None:
        """ Clear footnotes on reset, and prepare for distinct document. """
        self.footnote_order: list[str] = []
        self.footnotes: OrderedDict[str, str] = OrderedDict()
        self.unique_prefix += 1
        self.found_refs = {}
        self.used_refs = set()

    def unique_ref(self, reference: str, found: bool = False) -> str:
        """ Get a unique reference if there are duplicates. """
        if not found:
            return reference

        original_ref = reference
        while reference in self.used_refs:
            ref, rest = reference.split(self.get_separator(), 1)
            m = RE_REF_ID.match(ref)
            if m:
                reference = '%s%d%s%s' % (m.group(1), int(m.group(2))+1, self.get_separator(), rest)
            else:
                reference = '%s%d%s%s' % (ref, 2, self.get_separator(), rest)

        self.used_refs.add(reference)
        if original_ref in self.found_refs:
            self.found_refs[original_ref] += 1
        else:
            self.found_refs[original_ref] = 1
        return reference

    def findFootnotesPlaceholder(
        self, root: etree.Element
    ) -> tuple[etree.Element, etree.Element, bool] | None:
        """ Return ElementTree Element that contains Footnote placeholder. """
        def finder(element):
            for child in element:
                if child.text:
                    if child.text.find(self.getConfig("PLACE_MARKER")) > -1:
                        return child, element, True
                if child.tail:
                    if child.tail.find(self.getConfig("PLACE_MARKER")) > -1:
                        return child, element, False
                child_res = finder(child)
                if child_res is not None:
                    return child_res
            return None

        res = finder(root)
        return res

