def _escape_cdata(text) -> str:
    # escape character data
    try:
        # it's worth avoiding do-nothing calls for strings that are
        # shorter than 500 character, or so.  assume that's, by far,
        # the most common case in most applications.
        if "&" in text:
            # Only replace & when not part of an entity
            text = RE_AMP.sub('&amp;', text)
        if "<" in text:
            text = text.replace("<", "&lt;")
        if ">" in text:
            text = text.replace(">", "&gt;")
        return text
    except (TypeError, AttributeError):  # pragma: no cover
        _raise_serialization_error(text)

def _escape_attrib(text: str) -> str:
    # escape attribute value
    try:
        if "&" in text:
            # Only replace & when not part of an entity
            text = RE_AMP.sub('&amp;', text)
        if "<" in text:
            text = text.replace("<", "&lt;")
        if ">" in text:
            text = text.replace(">", "&gt;")
        if "\"" in text:
            text = text.replace("\"", "&quot;")
        if "\n" in text:
            text = text.replace("\n", "&#10;")
        return text
    except (TypeError, AttributeError):  # pragma: no cover
        _raise_serialization_error(text)

def _escape_attrib_html(text: str) -> str:
    # escape attribute value
    try:
        if "&" in text:
            # Only replace & when not part of an entity
            text = RE_AMP.sub('&amp;', text)
        if "<" in text:
            text = text.replace("<", "&lt;")
        if ">" in text:
            text = text.replace(">", "&gt;")
        if "\"" in text:
            text = text.replace("\"", "&quot;")
        return text
    except (TypeError, AttributeError):  # pragma: no cover
        _raise_serialization_error(text)

def _serialize_html(write: Callable[[str], None], elem: Element, format: Literal["html", "xhtml"]) -> None:
    stack: deque[Element | str] = deque([elem])

    count = 0
    while stack:
        count += 1
        el = stack.popleft()

        if isinstance(el, str):
            write(el)
            continue

        tag = el.tag
        text = el.text

        if tag is Comment:
            write(f"<!--{_escape_cdata(text)}-->")
        elif tag is ProcessingInstruction:
            write(f"<?{_escape_cdata(text)}?>")
        elif tag is None:
            if text:
                write(_escape_cdata(text))
            # Add the children in reverse order so we process them in the right order.
            if el.tail:
                stack.appendleft(_escape_cdata(el.tail))
            stack.extendleft(reversed(el))
            continue
        else:
            namespace_uri = None
            if isinstance(tag, QName):
                # `QNAME` objects store their data as a string: `{uri}tag`
                if tag.text[:1] == "{":
                    namespace_uri, tag = tag.text[1:].split("}", 1)
                else:
                    raise ValueError('QName objects must define a tag.')
            write(f"<{tag}")
            items = el.items()
            if items:
                items = sorted(items)  # lexical order
                for k, v in items:
                    if isinstance(k, QName):
                        # Assume a text only `QName`
                        k = k.text
                    if isinstance(v, QName):
                        # Assume a text only `QName`
                        v = v.text
                    if v is None:
                        # A valueless attribute is preserved exactly as it
                        # was provided: render the bare attribute name.
                        write(f" {k}")
                    else:
                        v = _escape_attrib_html(v)
                        if k == v and format == 'html' and k in BOOLEAN_ATTRIBUTES['html']:
                            # handle boolean attributes
                            write(f" {v}")
                        else:
                            write(f' {k}="{v}"')
            if namespace_uri:
                write(f' xmlns="{_escape_attrib(namespace_uri)}"')
            if format == "xhtml" and tag.lower() in HTML_EMPTY:
                write(" />")
            else:
                write(">")
                if text:
                    if tag.lower() in ["script", "style"]:
                        write(text)
                    else:
                        write(_escape_cdata(text))
                # Add the tail, end tag, and then the children in reverse order.
                # Since we pop from the left, this will ensure results are ordered correctly.
                if el.tail:
                    stack.appendleft(_escape_cdata(el.tail))
                if tag.lower() not in HTML_EMPTY:
                    stack.appendleft(f"</{tag}>")
                stack.extendleft(reversed(el))
                continue
        if el.tail:
            write(_escape_cdata(el.tail))

def _write_html(root: Element, format: Literal["html", "xhtml"] = "html") -> str:
    assert root is not None
    data: list[str] = []
    write = data.append
    _serialize_html(write, root, format)
    return "".join(data)

def to_html_string(element: Element) -> str:
    """ Serialize element and its children to a string of HTML5. """
    return _write_html(ElementTree(element).getroot(), format="html")

def to_xhtml_string(element: Element) -> str:
    """ Serialize element and its children to a string of XHTML. """
    return _write_html(ElementTree(element).getroot(), format="xhtml")

