def isString(s: object) -> bool:
    """ Return `True` if object is a string but not an  [`AtomicString`][markdown.util.AtomicString]. """
    if not isinstance(s, util.AtomicString):
        return isinstance(s, str)
    return False

def __processPlaceholders(
    self,
    data: str | None,
    parent: etree.Element,
    isText: bool = True
) -> list[tuple[etree.Element, list[str]]]:
    """
    Process string with placeholders and generate `ElementTree` tree.

    Arguments:
        data: String with placeholders instead of `ElementTree` elements.
        parent: Element, which contains processing inline data.
        isText: Boolean variable, True - it's text, False - it's a tail.

    Returns:
        List with `ElementTree` elements with applied inline patterns.

    """
    def linkText(text: str | None) -> None:
        if text:
            if result:
                if result[-1][0].tail:
                    result[-1][0].tail += text
                else:
                    result[-1][0].tail = text
            elif not isText:
                if parent.tail:
                    parent.tail += text
                else:
                    parent.tail = text
            else:
                if parent.text:
                    parent.text += text
                else:
                    parent.text = text
    result = []
    strartIndex = 0
    while data:
        index = data.find(self.__placeholder_prefix, strartIndex)
        if index != -1:
            id, phEndIndex = self.__findPlaceholder(data, index)

            if id in self.stashed_nodes:
                node = self.stashed_nodes.get(id)

                if index > 0:
                    text = data[strartIndex:index]
                    linkText(text)

                if not isinstance(node, str):  # it's Element
                    for child in [node] + list(node):
                        if child.tail:
                            if child.tail.strip():
                                self.__processElementText(
                                    node, child, False
                                )
                        if child.text:
                            if child.text.strip():
                                self.__processElementText(child, child)
                else:  # it's just a string
                    linkText(node)
                    strartIndex = phEndIndex
                    continue

                strartIndex = phEndIndex
                result.append((node, self.ancestors[:]))

            else:  # wrong placeholder
                end = index + len(self.__placeholder_prefix)
                linkText(data[strartIndex:end])
                strartIndex = end
        else:
            text = data[strartIndex:]
            if isinstance(data, util.AtomicString):
                # We don't want to loose the `AtomicString`
                text = util.AtomicString(text)
            linkText(text)
            data = ""

    return result

def linkText(text: str | None) -> None:
    if text:
        if result:
            if result[-1][0].tail:
                result[-1][0].tail += text
            else:
                result[-1][0].tail = text
        elif not isText:
            if parent.tail:
                parent.tail += text
            else:
                parent.tail = text
        else:
            if parent.text:
                parent.text += text
            else:
                parent.text = text

def __applyPattern(
    self,
    pattern: inlinepatterns.Pattern,
    data: str,
    patternIndex: int,
    startIndex: int = 0
) -> tuple[str, bool, int]:
    """
    Check if the line fits the pattern, create the necessary
    elements, add it to `stashed_nodes`.

    Arguments:
        data: The text to be processed.
        pattern: The pattern to be checked.
        patternIndex: Index of current pattern.
        startIndex: String index, from which we start searching.

    Returns:
        String with placeholders instead of `ElementTree` elements.

    """
    new_style = isinstance(pattern, inlinepatterns.InlineProcessor)

    for exclude in pattern.ANCESTOR_EXCLUDES:
        if exclude.lower() in self.ancestors:
            return data, False, 0

    if new_style:
        match = None
        # Since `handleMatch` may reject our first match,
        # we iterate over the buffer looking for matches
        # until we can't find any more.
        for match in pattern.getCompiledRegExp().finditer(data, startIndex):
            node, start, end = pattern.handleMatch(match, data)
            if start is None or end is None:
                startIndex += match.end(0)
                match = None
                continue
            break
    else:  # pragma: no cover
        match = pattern.getCompiledRegExp().match(data[startIndex:])
        leftData = data[:startIndex]

    if not match:
        return data, False, 0

    if not new_style:  # pragma: no cover
        node = pattern.handleMatch(match)
        start = match.start(0)
        end = match.end(0)

    if node is None:
        return data, True, end

    if not isinstance(node, str):
        if not isinstance(node.text, util.AtomicString):
            # We need to process current node too
            for child in [node] + list(node):
                if not isString(node):
                    if child.text:
                        self.ancestors.append(child.tag.lower())
                        child.text = self.__handleInline(
                            child.text, patternIndex + 1
                        )
                        self.ancestors.pop()
                    if child.tail:
                        child.tail = self.__handleInline(
                            child.tail, patternIndex
                        )

    placeholder = self.__stashNode(node, pattern.type())

    if new_style:
        # Return the index just past the inserted placeholder so the
        # next call scans only the unprocessed tail. Scanning from 0
        # after every match makes repeated inline patterns quadratic.
        return "{}{}{}".format(data[:start],
                               placeholder, data[end:]), True, start + len(placeholder)
    else:  # pragma: no cover
        return "{}{}{}{}".format(leftData,
                                 match.group(1),
                                 placeholder, match.groups()[-1]), True, (
            len(leftData) + len(match.group(1)) + len(placeholder)
        )

def __build_ancestors(self, parent: etree.Element | None, parents: list[str]) -> None:
    """Build the ancestor list."""
    ancestors = []
    while parent is not None:
        if parent is not None:
            ancestors.append(parent.tag.lower())
        parent = self.parent_map.get(parent)
    ancestors.reverse()
    parents.extend(ancestors)

class PrettifyTreeprocessor(Treeprocessor):
    """ Add line breaks to the html document. """

    def _prettifyETree(self, elem: etree.Element) -> None:
        """ Recursively add line breaks to `ElementTree` children. """

        i = "\n"
        if self.md.is_block_level(elem.tag) and elem.tag not in ['code', 'pre']:
            if (not elem.text or not elem.text.strip()) \
                    and len(elem) and self.md.is_block_level(elem[0].tag):
                elem.text = i
            for e in elem:
                if self.md.is_block_level(e.tag):
                    self._prettifyETree(e)
        if not elem.tail or not elem.tail.strip():
            elem.tail = i

    def run(self, root: etree.Element) -> None:
        """ Add line breaks to `Element` object and its children. """

        self._prettifyETree(root)
        # Do `<br />`'s separately as they are often in the middle of
        # inline content and missed by `_prettifyETree`.
        brs = root.iter('br')
        for br in brs:
            if not br.tail or not br.tail.strip():
                br.tail = '\n'
            else:
                br.tail = '\n%s' % br.tail
        # Clean up extra empty lines at end of code blocks.
        pres = root.iter('pre')
        for pre in pres:
            if len(pre) and pre[0].tag == 'code':
                code = pre[0]
                # Only prettify code containing text only
                if not len(code) and code.text is not None:
                    code.text = util.AtomicString(code.text.rstrip() + '\n')

def _prettifyETree(self, elem: etree.Element) -> None:
    """ Recursively add line breaks to `ElementTree` children. """

    i = "\n"
