def testCustomPygmentsFormatter(self):
    if has_pygments:
        class CustomFormatter(pygments.formatters.HtmlFormatter):
            def wrap(self, source, outfile):
                return self._wrap_div(self._wrap_code(source))

            def _wrap_code(self, source):
                yield 0, '<code>'
                for i, t in source:
                    if i == 1:
                        t += '<br>'
                    yield i, t
                yield 0, '</code>'

        expected = '''
        <div class="codehilite"><code>hello world
        <br>hello another world
        <br></code></div>
        '''

    else:
        CustomFormatter = None
        expected = '''
        <pre class="codehilite"><code>hello world
        hello another world
        </code></pre>
        '''

    self.assertMarkdownRenders(
        self.dedent(
            '''
            ```
            hello world
            hello another world
            ```
            '''
        ),
        self.dedent(
            expected
        ),
        extensions=[
            markdown.extensions.codehilite.CodeHiliteExtension(
                pygments_formatter=CustomFormatter,
                guess_lang=False,
            ),
            'fenced_code'
        ]
    )

class CustomFormatter(pygments.formatters.HtmlFormatter):
    def wrap(self, source, outfile):
        return self._wrap_div(self._wrap_code(source))

    def _wrap_code(self, source):
        yield 0, '<code>'
        for i, t in source:
            if i == 1:
                t += '<br>'
            yield i, t
        yield 0, '</code>'

def _wrap_code(self, source):
    yield 0, '<code>'
    for i, t in source:
        if i == 1:
            t += '<br>'
        yield i, t
    yield 0, '</code>'

class CustomAddLangHtmlFormatter(pygments.formatters.HtmlFormatter):
    def __init__(self, lang_str='', **options):
        super().__init__(**options)
        self.lang_str = lang_str

    def _wrap_code(self, source):
        yield 0, f'<code class="{self.lang_str}">'
        yield from source
        yield 0, '</code>'

def __init__(self, lang_str='', **options):
    super().__init__(**options)
